<style>
/* CRM A7.4.6 — one scoped stylesheet; navy/teal CRM design. */
.crm-team-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:19px}
.crm-team-stat{padding:19px 22px;min-width:0}.crm-team-stat span{display:block;color:#7d8797;font-size:11px;font-weight:650}.crm-team-stat strong{display:block;margin:8px 0 3px;font-size:25px;font-weight:750;color:#17284f}.crm-team-stat small{font-size:10px;color:#8a94a6}
.crm-team-security{display:flex;align-items:flex-start;gap:11px;margin:0 0 19px;padding:14px 17px;background:#f5f9fc;border:1px solid #dce8f1;border-radius:9px;font-size:11px;line-height:1.7;color:#667790}
.crm-team-security>span{font-size:18px;line-height:1.2;font-weight:800;color:#43698a}.crm-team-security strong{display:block;color:#17284f;font-size:12px}.crm-team-security.in-card{margin-bottom:13px}
.crm-team-panel{margin-bottom:20px}.crm-team-panel .card-head h3{font-size:15px;color:#17284f;margin:0 0 4px}.crm-team-panel .card-head p{font-size:11px;color:#8893a3;margin:0}
.crm-team-filters{display:flex;gap:11px;align-items:flex-end;flex-wrap:wrap;margin-bottom:18px}.crm-team-field{display:flex;flex-direction:column;gap:7px;min-width:0;flex:1 1 150px}.crm-team-field label{font-size:11px;color:#34415c;font-weight:700}.crm-team-field b{color:#cc4850}.crm-team-field input,.crm-team-field select,.crm-team-field textarea{display:block;box-sizing:border-box;width:100%;min-height:40px;padding:9px 11px;border:1px solid #d9dee8;border-radius:8px;background:#fff;color:#283a56;font-size:12px;outline:none;font-family:inherit;transition:border-color .15s,box-shadow .15s}.crm-team-field textarea{resize:vertical;min-height:82px}.crm-team-field input:focus,.crm-team-field select:focus,.crm-team-field textarea:focus{border-color:#2ba7a0;box-shadow:0 0 0 3px rgba(43,167,160,.08)}.crm-team-field small{color:#8a94a6;font-size:10px;line-height:1.55}.crm-team-field .crm-team-error{color:#c84449}.crm-team-search{flex:2 1 210px}.crm-team-filter-actions{display:flex;gap:8px;align-items:center;padding-bottom:0}
.crm-team-table-wrap{border:1px solid #cbd5e1;border-radius:9px;overflow-x:auto}.crm-team-table{border-collapse:collapse;width:100%;min-width:810px}.crm-team-table th{padding:13px 14px;background:#f3f5f9;color:#34415c;text-align:left;font-weight:700;font-size:11px;border-bottom:1px solid #cbd5e1;border-right:1px solid #d8dee9;white-space:nowrap}.crm-team-table td{padding:14px;border-right:1px solid #e4e8ef;border-bottom:1px solid #e4e8ef;color:#526078;font-size:12px;vertical-align:middle}.crm-team-table th:last-child,.crm-team-table td:last-child{border-right:0}.crm-team-table tbody tr:last-child td{border-bottom:0}.crm-team-table tbody tr:hover{background:#fafcfe}
.crm-team-title{display:block;color:#17284f;font-weight:700;text-decoration:none;font-size:12px}.crm-team-title:hover{color:#168b85}.crm-team-subtitle{display:block;color:#8a94a6;margin-top:5px;letter-spacing:.4px;font-size:10px}.crm-team-tag{display:inline-flex;align-items:center;justify-content:center;font-size:10px;white-space:nowrap;font-weight:700;border-radius:7px;padding:6px 9px}.crm-team-tag.teal{color:#167d70;background:#eaf7f3}.crm-team-tag.indigo{color:#5362a7;background:#eef1ff}.crm-team-tag.gray{color:#697589;background:#f0f2f5}.crm-team-actions{display:flex;gap:8px}.crm-team-action{color:#344e71;background:#f6f8fc;border:1px solid #e0e6ee;padding:6px 10px;border-radius:7px;font-size:11px;font-weight:700;text-decoration:none}.crm-team-action:hover{border-color:#2ba7a0;color:#167d70}.crm-team-empty{text-align:center;padding:25px;color:#8590a1}.crm-team-empty strong{display:block;font-size:14px;color:#34415c}.crm-team-empty p{font-size:11px;margin:8px 0 15px}.crm-team-pagination{display:flex;justify-content:center;margin-top:18px}
.crm-team-form-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,.62fr);align-items:start;gap:19px}.crm-team-editor .card-body{padding:24px}.crm-team-section+.crm-team-section{margin-top:27px;padding-top:25px;border-top:1px solid #e8edf2}.crm-team-section-head{margin-bottom:17px}.crm-team-section-head h4{font-size:13px;color:#17284f;margin:0 0 5px}.crm-team-section-head p{font-size:11px;color:#8a94a6;margin:0;line-height:1.6}.crm-team-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:17px}.crm-team-wide{grid-column:1/-1}.crm-team-form-grid [hidden]{display:none!important}.crm-team-error{font-size:11px;color:#bf424c}.crm-team-form-actions{display:flex;justify-content:flex-end;gap:9px;border-top:1px solid #e8edf2;margin-top:27px;padding-top:20px}
.crm-team-member-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.crm-team-member-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:17px 0 11px}.crm-team-member-toolbar>span{color:#64748b;font-size:11px;font-weight:700}.crm-team-member-toolbar>div{display:flex;gap:8px}.crm-team-member-toolbar .btn{font-size:11px;padding:7px 10px;min-height:32px}.crm-team-member-list{max-height:350px;overflow:auto;border:1px solid #d8e0eb;border-radius:9px;background:#fff}.crm-team-member-row{display:flex;align-items:center;gap:12px;padding:12px 13px;border-bottom:1px solid #edf0f5;cursor:pointer;transition:background .15s}.crm-team-member-row:last-child{border-bottom:0}.crm-team-member-row:hover{background:#f8fafc}.crm-team-member-row[hidden]{display:none!important}.crm-team-member-row input{width:16px;height:16px;accent-color:#168b85;flex:0 0 16px;margin:0}.crm-team-member-identity{min-width:0;flex:1}.crm-team-member-identity strong{display:block;color:#17284f;font-size:12px;font-weight:700}.crm-team-member-identity small{display:block;color:#8a94a6;font-size:10px;margin-top:4px;overflow-wrap:anywhere}.crm-team-member-branch{color:#62748c;font-size:10px;white-space:nowrap}.crm-team-member-help{font-size:10px;color:#8591a3;margin:11px 0 0;line-height:1.7}.crm-team-member-help.invalid{color:#bc4a48;font-weight:600}.crm-team-person-avatar{width:34px;height:34px;min-width:34px;display:grid;place-items:center;border-radius:9px;background:#eaf7f3;color:#167d70;font-size:12px;font-weight:800}
.crm-team-preview{position:sticky;top:24px;padding:24px;min-width:0}.crm-team-preview-label{letter-spacing:1.5px;color:#8a94a6;font-size:10px;font-weight:750}.crm-team-preview-symbol{height:45px;width:45px;display:grid;place-items:center;background:#eaf7f3;color:#167d70;border-radius:11px;font-weight:800;margin:20px 0 11px}.crm-team-preview>h3{font-size:17px;color:#17284f;margin:0 0 5px;overflow-wrap:anywhere}.crm-team-preview>p{color:#8a94a6;font-size:11px;margin:0 0 20px;overflow-wrap:anywhere}.crm-team-preview-detail{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:12px 0;border-top:1px solid #edf0f5}.crm-team-preview-detail>span{font-size:11px;color:#8a94a6}.crm-team-preview-detail>strong{font-size:11px;color:#34415c;text-align:right;max-width:62%;overflow-wrap:anywhere}.crm-team-preview-notice{padding:13px;border-radius:8px;background:#f5f9fc;margin-top:13px}.crm-team-preview-notice strong{font-size:11px;color:#34415c}.crm-team-preview-notice p{color:#8692a5;font-size:10px;line-height:1.7;margin:5px 0 0}
.crm-team-detail-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(255px,.75fr);gap:18px;align-items:start}.crm-team-detail-identity{display:flex;gap:12px;align-items:center;margin-bottom:23px}.crm-team-detail-identity h3{margin:0 0 5px;color:#17284f;font-size:17px}.crm-team-detail-identity small{color:#94a0b1;letter-spacing:.6px;font-size:11px}.crm-team-avatar{width:48px;height:48px;min-width:48px;display:grid;place-items:center;background:#eaf7f3;color:#167d70;border-radius:11px;font-size:18px;font-weight:800}.crm-team-data-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 20px}.crm-team-data-grid span{display:block;color:#8a94a6;font-size:10px;margin-bottom:6px}.crm-team-data-grid strong{display:block;color:#34415c;font-size:12px;word-wrap:break-word}.crm-team-description{border-top:1px solid #edf0f5;margin-top:22px;padding-top:17px}.crm-team-description strong{font-size:12px;color:#17284f}.crm-team-description p{font-size:12px;white-space:pre-wrap;line-height:1.8;color:#65758e}.crm-team-side-note{color:#758397;font-size:11px;line-height:1.8}.crm-team-muted{display:block;margin-top:11px;font-size:10px;color:#8793a3;line-height:1.7}.crm-team-count{color:#7d8a9d;font-size:11px;font-weight:700}.crm-team-person{display:flex;align-items:center;gap:10px}.crm-team-person strong{font-size:12px;color:#17284f}.crm-team-person small{display:block;margin-top:4px;color:#8a94a6;font-size:10px}.crm-team-danger{color:#ad3a43;border-color:#ecd0d4}.crm-team-danger:hover{background:#fdf3f4;border-color:#cf8f99}
@media(max-width:1180px){.crm-team-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.crm-team-form-layout{grid-template-columns:minmax(0,1fr)}.crm-team-preview{position:static}.crm-team-detail-grid{grid-template-columns:1fr}}
@media(max-width:800px){.crm-team-member-controls{grid-template-columns:1fr 1fr}.crm-team-member-branch{display:none}.crm-team-preview{padding:19px}}
@media(max-width:620px){.crm-team-stats{grid-template-columns:1fr 1fr}.crm-team-stat{padding:13px}.crm-team-form-grid,.crm-team-member-controls,.crm-team-data-grid{grid-template-columns:1fr}.crm-team-editor .card-body{padding:16px}.crm-team-form-actions{flex-direction:column-reverse}.crm-team-form-actions .btn{justify-content:center}.crm-team-member-toolbar>div{width:100%}.crm-team-member-toolbar>div .btn{flex:1;justify-content:center}}
</style>
